inline const GST *GetGST(const void *buf) {
  return ::flatbuffers::GetRoot<GST>(buf);
}

inline const GST *GetSizePrefixedGST(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<GST>(buf);
}

inline const char *GSTIdentifier() {
  return "$GST";
}

inline bool GSTBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, GSTIdentifier());
}

inline bool SizePrefixedGSTBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, GSTIdentifier(), true);
}

template <bool B = false>
inline bool VerifyGSTBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<GST>(GSTIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedGSTBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<GST>(GSTIdentifier());
}

inline void FinishGSTBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<GST> root) {
  fbb.Finish(root, GSTIdentifier());
}

inline void FinishSizePrefixedGSTBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<GST> root) {
  fbb.FinishSizePrefixed(root, GSTIdentifier());
}

